-- [annotate] resolution strategies:
--   order_id: identity
--   amount: lastmodified
--   person_ref: coalesce
-- Resolution: global_order
SELECT pgtrickle.create_stream_table_if_not_exists(
    name => '_resolved_global_order',
    query => $pgtrickle_q$
SELECT
  _entity_id_resolved AS _entity_id,
  min("order_id") AS "order_id",
  (array_agg("amount" ORDER BY COALESCE("_ts_amount", _last_modified) DESC NULLS LAST) FILTER (WHERE "amount" IS NOT NULL))[1] AS "amount",
  (array_agg("person_ref" ORDER BY 0 ASC, COALESCE("_priority_person_ref", _priority, 999) ASC NULLS LAST) FILTER (WHERE "person_ref" IS NOT NULL))[1] AS "person_ref"
FROM "_id_global_order"
GROUP BY _entity_id_resolved
