--     WHERE o.person_ref = global_person.person_id
--   ), 0)
-- Resolution: global_person
SELECT pgtrickle.create_stream_table_if_not_exists(
    name => '_resolved_global_person',
    query => $pgtrickle_q$
WITH
  "_echo" AS (
    SELECT *,
      ROW_NUMBER() OVER (
        PARTITION BY _entity_id_resolved, "_normalize_name"
        ORDER BY "_has_normalize_name" ASC, COALESCE("_ts_name", _last_modified) DESC NULLS LAST
      ) AS "_echo_rank_name"
    FROM "_id_global_person"
  )
SELECT
  _entity_id_resolved AS _entity_id,
  min("person_id") AS "person_id",
  (array_agg("type" ORDER BY 0 ASC, COALESCE("_priority_type", _priority, 999) ASC NULLS LAST) FILTER (WHERE "type" IS NOT NULL))[1] AS "type",
  (array_agg("name" ORDER BY COALESCE("_ts_name", _last_modified) DESC NULLS LAST) FILTER (WHERE "name" IS NOT NULL AND "_echo_rank_name" = 1))[1] AS "name",
  (array_agg("age" ORDER BY COALESCE("_ts_age", _last_modified) DESC NULLS LAST) FILTER (WHERE "age" IS NOT NULL))[1] AS "age"
FROM "_echo"
GROUP BY _entity_id_resolved
$pgtrickle_q$
);
