  NULLIF(to_jsonb(r)->>'_order_rank_order_count', '')::bigint AS "_order_rank_order_count",
  id._base
FROM "_enriched_global_person" AS r
LEFT JOIN (SELECT _src_id, _mapping, _entity_id_resolved, _base, "person_id" FROM "_id_global_person") AS id
  ON id._entity_id_resolved = r._entity_id
    AND id._mapping = 'person_with_orders_person'
$pgtrickle_q$
);
CREATE UNIQUE INDEX IF NOT EXISTS "idx__rev_person_with_orders_person"
  ON "_rev_person_with_orders_person" ("_cluster_id", "_src_id")
  NULLS NOT DISTINCT;

-- Delta for source: person
-- Delta: person (change detection)
SELECT pgtrickle.create_stream_table_if_not_exists(
    name => '_delta_person',
    query => $pgtrickle_q$
SELECT
  CASE
      WHEN _src_id IS NULL THEN 'insert'
      WHEN _base->>'name' IS NOT DISTINCT FROM "name"::text AND _base->>'age' IS NOT DISTINCT FROM "age"::text THEN 'noop'
      ELSE 'update'
    END AS _action,
  "_cluster_id",
  "_id",
  "name",
  "age",
  "_base"
FROM "_rev_person"
$pgtrickle_q$
);
CREATE UNIQUE INDEX IF NOT EXISTS "idx__delta_person"
  ON "_delta_person" ("_cluster_id", "_id")
  NULLS NOT DISTINCT;

-- Delta for source: person_with_orders
-- Delta: person_with_orders (change detection)
SELECT pgtrickle.create_stream_table_if_not_exists(
    name => '_delta_person_with_orders',
    query => $pgtrickle_q$
WITH _nested_orders AS (
SELECT n."parent_id" AS _parent_key, COALESCE(jsonb_agg(jsonb_build_object('order_id', n."order_id", 'amount', n."amount") ORDER BY n."amount" DESC NULLS LAST, n."order_id"), '[]'::jsonb) AS "orders"
FROM "_rev_person_with_orders_orders" AS n
WHERE n."parent_id" IS NOT NULL AND NOT (n."order_id" IS NULL AND n."amount" IS NULL)
GROUP BY n."parent_id"
)
SELECT
  CASE
      WHEN p._src_id IS NULL THEN 'insert'
      WHEN p._base->>'name' IS NOT DISTINCT FROM p."name"::text AND p._base->>'type' IS NOT DISTINCT FROM p."type"::text AND p._base->>'age' IS NOT DISTINCT FROM p."age"::text AND COALESCE(_osi_text_norm(p._base->'orders')::text, '[]') IS NOT DISTINCT FROM COALESCE(_osi_text_norm(_nested_orders."orders")::text, '[]') THEN 'noop'
      ELSE 'update'
    END AS _action,
  p."_cluster_id",
  p."_id",
  p."name",
  p."type",
  p."age",
  p."order_count",
  COALESCE(_nested_orders."orders", '[]'::jsonb) AS "orders",
  p."_base"
FROM "_rev_person_with_orders_person" AS p
LEFT JOIN _nested_orders ON _nested_orders._parent_key = CASE WHEN p._src_id IS NULL THEN p."_cluster_id" ELSE p."_id"::text END
$pgtrickle_q$
);
CREATE UNIQUE INDEX IF NOT EXISTS "idx__delta_person_with_orders"
  ON "_delta_person_with_orders" ("_cluster_id", "_id")
  NULLS NOT DISTINCT;

-- Refresh materialized views in dependency order
SELECT pgtrickle.refresh_stream_table('_fwd_orders');
SELECT pgtrickle.refresh_stream_table('_fwd_person_with_orders_orders');
SELECT pgtrickle.refresh_stream_table('_fwd_person_with_orders_person');
SELECT pgtrickle.refresh_stream_table('_fwd_person');
SELECT pgtrickle.refresh_stream_table('_id_global_order');
SELECT pgtrickle.refresh_stream_table('_id_global_person');
SELECT pgtrickle.refresh_stream_table('_resolved_global_order');
SELECT pgtrickle.refresh_stream_table('_resolved_global_person');
SELECT pgtrickle.refresh_stream_table('global_order');
SELECT pgtrickle.refresh_stream_table('_rev_orders');
SELECT pgtrickle.refresh_stream_table('_rev_person_with_orders_orders');
SELECT pgtrickle.refresh_stream_table('_enriched_global_person');
SELECT pgtrickle.refresh_stream_table('_delta_orders');
SELECT pgtrickle.refresh_stream_table('global_person');
SELECT pgtrickle.refresh_stream_table('_rev_person');
SELECT pgtrickle.refresh_stream_table('_rev_person_with_orders_person');
SELECT pgtrickle.refresh_stream_table('_delta_person');
SELECT pgtrickle.refresh_stream_table('_delta_person_with_orders');

COMMIT;
